bug_report:
[modules] ICE: canonical types differ for identical types
Consider the following:


  // test.hpp
  template <typename> struct A;
  template <typename T> struct A<T*> {};
  template <typename T> struct B { static A<T*> x; };
  using C = B<int>;

  // a.cpp
  module;
  #include "test.hpp"
  export module A;
  C c1;

  // b.cpp
  module;
  #include "test.hpp"
  export module B;
  import A;
  C c2;

  // c.cpp
  template <typename> struct A {};
  template <typename T> struct B { static A<T*> x; };
  template struct B<int>;
  import B;


